'use strict';
const E=LifeEngine,$=id=>document.getElementById(id),money=n=>Math.round(n).toLocaleString('zh-TW'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storeKey='financial-life-lab-v1';let state=null,timer=null,latest=null;const symbols={market:'◎',accident:'✚',work:'▣',social:'♡'};
const positions=[];for(let c=1;c<=6;c++)positions.push([1,c]);for(let r=2;r<=6;r++)positions.push([r,6]);for(let c=5;c>=1;c--)positions.push([6,c]);for(let r=5;r>=2;r--)positions.push([r,1]);
positions.forEach(([row,col],i)=>{const tile=document.createElement('div'),cat=E.CATEGORIES[i%4];tile.className='tile '+cat;tile.id='tile-'+i;tile.style.gridRow=row;tile.style.gridColumn=col;tile.innerHTML=`<span class="tile-index">${String(i+1).padStart(2,'0')}</span><span class="tile-symbol">${symbols[cat]}</span><span>${E.LABELS[cat]}</span>`;$('board').append(tile);});
function save(){try{localStorage.setItem(storeKey,JSON.stringify({state,latest}));}catch(e){message('瀏覽器儲存空間不可用，離開頁面後進度可能無法保留。',true);}}
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);}
function pause(){if(timer)clearInterval(timer);timer=null;$('pause').textContent='自動前進';}
function render(){if(!state)return;const s=state,net=E.net(s),flow=E.income(s)-E.outgo(s),liquid=s.cash+s.stocks+s.bonds,months=E.outgo(s)>0?s.cash/(E.outgo(s)/12):0;$('client-name').textContent=s.name;$('client-detail').textContent=`${s.job} · ${s.married==='yes'?'已婚／伴侶':'單身'} · 扶養 ${s.dependents} 人`;$('phase').textContent=s.ended?'人生已結束':s.age>=65?'退休階段':'工作階段';$('age').textContent=s.age+' 歲';$('family').textContent=`子女 ${s.children} 人 · ${s.health==='chronic'?'慢性疾病':'無已知疾病'}`;$('net').textContent=money(net);$('net-change').textContent=`相較起點 ${net-s.startNet>=0?'+':''}${money(net-s.startNet)} 元`;$('cash').textContent=money(s.cash);$('runway').textContent=E.outgo(s)>0?`可支應約 ${months.toFixed(1)} 個月支出`:'目前沒有支出';$('flow').textContent=(flow>=0?'+':'')+money(flow);$('flow').classList.toggle('negative',flow<0);$('market-label').textContent=E.MARKETS[s.market].name;document.querySelectorAll('.tile').forEach((t,i)=>{t.classList.toggle('active',i===s.position);if(i===s.position)t.setAttribute('aria-current','step');else t.removeAttribute('aria-current');});$('roll').hidden=s.remaining>0||s.ended;$('travel-controls').hidden=s.remaining===0||s.ended;$('remaining').textContent=`還有 ${s.remaining} 格 · ${s.remaining/2} 年到下次事件`;$('dice').textContent=s.die?['⚀','⚁','⚂','⚃','⚄','⚅'][s.die-1]:'⚄';$('journey-title').textContent=s.ended?(s.reason==='death'?'人生抵達終點。':'財務無法繼續。'):s.remaining>0?'讓時間慢慢前進。':'下一段人生，會如何？';$('journey-description').innerHTML=s.ended?'查看回顧，理解每次選擇留下的結果。':s.remaining>0?'每一步半年，途中可打開規劃背包。<br>落點才會觸發下一張事件卡。':'大點數代表較長的平穩期。<br>先確認規劃，再走向下一次事件。';
  const colors={cash:'#93ae83',stocks:'#23654c',bonds:'#c5b079',property:'#bcc4b3'},names={cash:'現金',stocks:'股票／股票基金',bonds:'債券／債券基金',property:'其他資產'},total=liquid+s.property;$('allocation').innerHTML=['cash','stocks','bonds','property'].map(k=>`<span style="width:${total?s[k]/total*100:0}%;background:${colors[k]}" title="${names[k]}"></span>`).join('');$('asset-list').innerHTML=['cash','stocks','bonds','property'].map(k=>`<div class="asset-row"><span><i style="background:${colors[k]}"></i>${names[k]}</span><strong>${money(s[k])}<small>${total?(s[k]/total*100).toFixed(0):0}%</small></strong></div>`).join('')+`<div class="asset-row"><span>負債</span><strong class="negative">−${money(s.debt)}</strong></div>`;$('asset-insight').textContent=months<6&&E.outgo(s)>0?`目前現金約能支應 ${months.toFixed(1)} 個月支出。若收入中斷，你可能需要變現投資。`:'現金準備讓你有較多應對空間；保障與投資仍要配合家庭責任及用錢時間。';$('policies').innerHTML=Object.entries(E.POLICIES).map(([k,p])=>`<article class="policy"><h3>${p.name}<span>${s.policies[k]?'● 已生效':'尚未投保'}</span></h3><p>${p.description}</p><div class="policy-price">年保費 NT$ ${money(p.premium)}</div><button class="${s.policies[k]?'secondary':'primary'}" data-policy="${k}" ${s.ended?'disabled':''}>${s.policies[k]?'取消後續保障':'加入這項保障'}</button></article>`).join('');$('budget-summary').innerHTML=`<div class="asset-row"><span>年度${s.age>=65?'退休':'工作'}收入</span><strong>${money(E.income(s))}</strong></div><div class="asset-row"><span>生活費</span><strong>${money(s.expense)}</strong></div><div class="asset-row"><span>保費</span><strong>${money(E.premium(s))}</strong></div><div class="asset-row"><span>還款本金＋利息</span><strong>${money(Math.min(s.repayment,s.debt)+s.debt*s.interest/100)}</strong></div>`;if(document.activeElement!==$('budget'))$('budget').value=s.expense;document.querySelectorAll('#transfer-form button,#budget-form button').forEach(b=>b.disabled=s.ended);$('history').innerHTML=s.history.slice(-50).reverse().map(h=>`<div class="history-entry"><time>${h.age} 歲</time><div><strong>${esc(h.title)}</strong><p>${esc(h.detail)}</p></div></div>`).join('');
  const values=s.series.map(p=>p.net),min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min);const points=s.series.map((p,i)=>`${s.series.length===1?0:i/(s.series.length-1)*320},${85-(p.net-min)/range*65}`).join(' ');$('chart').innerHTML=`<svg viewBox="0 0 320 100" role="img" aria-label="淨資產由${money(s.startNet)}變為${money(net)}"><path d="M0 88 H320" stroke="#e3e7dc"/><polyline points="${points}" fill="none" stroke="#23654c" stroke-width="2.5" stroke-linejoin="round"/></svg><div class="chart-labels"><span>${s.startAge} 歲 · ${money(s.startNet)}</span><span>${s.age} 歲 · ${money(net)}</span></div>`;save();}
function showEvent(e){latest=e;$('event-card').innerHTML=`<div class="event-icon">${symbols[e.cat]||'↗'}</div><div><span class="eyebrow">${E.LABELS[e.cat]||'人生結算'} · ${state.age} 歲</span><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>${e.numbers?`<div class="event-numbers"><span>費用 ${money(e.numbers.loss)}</span><span>保障給付 ${money(e.numbers.claim)}</span><span>自付 ${money(e.numbers.own)}</span></div>`:''}<p style="margin-top:10px">✧ ${esc(e.lesson)}</p></div>`;}
function step(){if(!state||state.ended)return;const result=E.advance(state);if(!result)return;message(`半年結算：收入 ${money(result.earned)}，支出 ${money(result.living+result.fees+result.interest+result.paid)}，投資變化 ${money(result.stocks+result.bonds)} 元。`);if(state.ended){pause();showEvent({cat:'accident',title:state.reason==='death'?'人生抵達終點':'可變現資產已耗盡',text:state.reason==='death'?state.deathCause:`仍有 ${money(state.shortfall)} 元到期支出無法支付。`,lesson:state.reason==='death'?'最後的財務安排，會留給家屬。查看人生回顧。':'破產按支付能力判定，房產不自動變現。查看人生回顧。'});}else if(state.remaining===0){pause();showEvent(E.event(state));}render();if(state.ended)openReport();}
$('roll').onclick=()=>{if(!state||state.ended||state.remaining)return;state.die=Math.floor(Math.random()*6)+1;state.remaining=state.die;message(`擲出 ${state.die} 點：到下次事件有 ${state.die/2} 年。可逐格前進或自動播放。`);render();};$('step').onclick=step;$('pause').onclick=()=>{if(timer){pause();return;}if(!state||!state.remaining||state.ended)return;$('pause').textContent='暫停時間';timer=setInterval(step,850);};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',t===b?'true':'false'));['assets','insurance','life'].forEach(k=>$('tab-'+k).hidden=k!==b.dataset.tab);});
$('transfer-form').onsubmit=e=>{e.preventDefault();const error=E.transfer(state,$('from').value,$('to').value,Number($('transfer-amount').value));message(error||'資金已移轉，總資產不變。',!!error);render();};$('policies').onclick=e=>{const b=e.target.closest('[data-policy]');if(!b)return;E.togglePolicy(state,b.dataset.policy);message('保障已更新，只適用此刻之後的事件。');render();};$('budget-form').onsubmit=e=>{e.preventDefault();const value=Number($('budget').value);if(!Number.isFinite(value)||value<0||!Number.isInteger(value)||state.ended){message('請輸入有效的年度生活支出。',true);return;}state.expense=value;state.history.push({age:state.age,title:'調整生活預算',detail:`年度生活支出調整為 ${money(value)} 元。`,kind:'decision'});message('生活預算已更新，下次結算生效。');render();};
$('setup-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));['age','income','expense','cash','stocks','bonds','property','debt','repayment','interest','pension','children','dependents'].forEach(k=>data[k]=Number(data[k]));if(data.dependents<data.children){e.target.elements.dependents.setCustomValidity('扶養人數需包含子女，不能少於子女數。');e.target.elements.dependents.reportValidity();return;}e.target.elements.dependents.setCustomValidity('');pause();state=E.create(data);latest=null;$('setup').close();showEvent({cat:'work',title:'這段人生，現在開始。',text:`${data.name}，${data.age}歲，年度收入 ${money(data.age>=65?data.pension:data.income)} 元，扶養 ${data.dependents} 人。`,lesson:'先調整保障、現金與投資，再擲骰；沒有出險，不代表保障沒有作用。'});message('客戶資料已建立。你可以先規劃，也可以直接擲骰。');render();if(state.ended)openReport();};$('setup-form').elements.dependents.oninput=e=>e.target.setCustomValidity('');$('setup-form').elements.children.oninput=()=>$('setup-form').elements.dependents.setCustomValidity('');
$('restart').onclick=()=>{pause();if(state&&!confirm('要開始一段新的人生嗎？送出新設定後會取代目前紀錄。'))return;$('setup').showModal();};$('setup').addEventListener('cancel',e=>{if(!state)e.preventDefault();});
function openReport(){if(!state)return;pause();const s=state,annual=E.outgo(s),familyYears=s.dependents>0?5:1,target=s.debt+s.expense*familyYears,resources=s.cash+s.stocks+s.bonds+s.survivorBenefit+(s.reason==='bankruptcy'?-s.shortfall:0),gap=Math.max(0,target-resources),title=s.ended?(s.reason==='death'?'人生結束，家庭的生活仍要繼續。':'財務走到需要重新安排的時刻。'):'人生還在繼續，先回顧你的安排。';$('report-content').innerHTML=`<h2>${title}</h2><p class="hint">${esc(s.name)} · ${s.startAge} → ${s.age} 歲 · ${s.periods/2} 年 · ${s.events} 次事件${s.reason==='death'?' · '+esc(s.deathCause):''}</p><div class="report-metrics"><div><small>結算淨資產${s.reason==='bankruptcy'?'（含未付缺口）':''}</small><strong>${money(E.net(s)-(s.reason==='bankruptcy'?s.shortfall:0))}</strong></div><div><small>累計保費</small><strong>${money(s.totalPremium)}</strong></div><div><small>累計保障給付（含家屬）</small><strong>${money(s.totalClaims)}</strong></div><div><small>因現金不足變現投資</small><strong>${money(s.forcedSales)}</strong></div></div><div class="report-copy"><p><strong>生活延續：</strong>${annual>0?`現金約能支應 ${(s.cash/(annual/12)).toFixed(1)} 個月目前支出。`:'目前未設定支出。'}${s.reason==='bankruptcy'?` 尚欠 ${money(s.shortfall)} 元未付支出。`:''}</p><p><strong>家庭保障：</strong>${s.reason==='death'?`家屬身故給付 ${money(s.survivorBenefit)} 元。`:`目前身故保障 ${money(s.policies.life?E.POLICIES.life.cover:0)} 元。`} 以清償負債＋${familyYears}年目前生活費作為教學壓力測試，${s.reason==='death'?'實際':'假設此刻身故的'}缺口約 ${money(Math.max(0,gap-(s.reason!=='death'&&s.policies.life?E.POLICIES.life.cover:0)))} 元。此估算未計家屬收入、未來通膨與房產出售。</p><p><strong>這段人生的收支：</strong>累計收入 ${money(s.totalIncome)}、生活費 ${money(s.totalExpense)}、利息 ${money(s.totalInterest)}、已償還本金 ${money(s.totalPrincipal)} 元。本金還款同時減少現金與負債。</p><p><strong>試著回答：</strong></p><ol><li>哪次事件影響最大？影響的是收入、資產，還是支出？</li><li>你的保障填補了什麼？還留下哪些不承保或超過上限的缺口？</li><li>如果市場下跌時不用賣投資，你會需要多少現金準備？</li></ol><p class="hint">本版沒有以財富或出險次數評分，也未完成個人目標、反事實比較與AI分析。壽命與市場模型僅用來展示流程。</p></div>`;if(!$('report-dialog').open)$('report-dialog').showModal();}
$('report').onclick=openReport;$('close-report').onclick=()=>$('report-dialog').close();$('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:'0.1',assumptions:'教學簡化模型，非正式商品或預測',state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='financial-life-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const saved=JSON.parse(localStorage.getItem(storeKey));if(saved?.state&&saved.state.policies&&Array.isArray(saved.state.history)){state=saved.state;latest=saved.latest;render();if(latest)showEvent(latest);}}catch(e){message('舊紀錄無法載入，請重新設定客戶。',true);}if(!state)$('setup').showModal();
